using TownOfHost;
using TownOfHost.Roles.Core;
using TownOfHost.Roles.Crewmate;
using TownOfHost.Patches;
using TownOfHost.Modules;
class Program {
 static int passed;
 static void Check(bool b,string m="assertion"){if(!b)throw new Exception(m);}
 static void Equal(float a,float b,string m="speed mismatch"){Check(Math.Abs(a-b)<.00001f,m+$": {a} != {b}");}
 static void Reset(){AmongUsClient.Instance.AmHost=true;Idol.Reset();CustomRoleManager.AllActiveRoles.Clear();CustomRoleManager.OnFixedUpdateOthers.Clear();CustomRoleManager.OnMurderPlayerOthers.Clear();CustomRoleManager.Sent.Clear();PlayerCatch.Players.Clear();PlayerState.States.Clear();TownOfHost.Main.AllPlayerSpeed.Clear();PetActionManager.Handlers.Clear();PetActionManager.RegisterCalls=PetActionManager.UnregisterCalls=0;FloatOptionItem.Registered.Clear();Idol.RoleInfo.OptionCreator();GameStates.InGame=true;GameStates.IsLobby=false;GameStates.IsInTask=true;GameStates.Intro=false;GameStates.IsMeeting=GameStates.CalledMeeting=false;UnityEngine.Time.fixedDeltaTime=.5f;ShipStatus.Instance=new();PhysicsHelpers.Blocked.Clear();PhysicsHelpers.Calls=0;TownOfHost.Roles.AddOns.Common.Amnesia.Blocked.Clear();GameOptionsSender.AllSenders.Clear();Logger.Entries.Clear();GameOptionsSender.LastSent.Clear();GameOptionsSender.Flushes=0;UtilsNotifyRoles.Calls=0;PlayerControl.LocalPlayer=PC(0,new(20,20));}
 static PlayerControl PC(byte id,UnityEngine.Vector2 pos=default){var p=new PlayerControl{PlayerId=id,Position=pos};PlayerCatch.Players[id]=p;PlayerState.States[id]=new();TownOfHost.Main.AllPlayerSpeed[id]=1f;GameOptionsSender.AllSenders.Add(new PlayerGameOptionsSender{player=p});return p;}
 static Idol Role(byte id=1){var r=new Idol(PC(id));r.Add();return r;}
 static void Tick(int count=1){for(int n=0;n<count;n++)foreach(var action in CustomRoleManager.OnFixedUpdateOthers.ToArray())action(PlayerControl.LocalPlayer);}
 static void Pet(Idol r)=>RealPetDispatch.OnPetUse(r.Player);
 static string Text(Idol r)=>r.GetLowerText(r.Player,isForHud:true);
 static void Ready(Idol r){r.MyTaskState.CompletedTasksCount=3;r.OnCompleteTask(1);Tick(40);}
 static void Start(Idol r){Ready(r);Pet(r);Check(Text(r).Contains("ファンサ中"),"not active");}
 static float Speed(PlayerControl p)=>RealSpeedPipeline.Build(p);
 static void Test(string n,Action t){Reset();t();passed++;Console.WriteLine("PASS "+n);}
 static void Main(){
 Test("metadata preserves crew base color ConfigId alias and Shell source",()=>{var i=Idol.RoleInfo;Check((int)i.RoleName==374&&i.BaseRoleType()==AmongUs.GameOptions.RoleTypes.Crewmate&&i.CustomRoleType==CustomRoleTypes.Crewmate&&i.ConfigId==40100&&i.ChatCommand=="idol"&&i.RoleColorCode=="#F8ABA6"&&i.From==From.TownOfHost_Shell&&i.IsNewRole);});
 Test("all five option IDs ranges steps defaults and formats match provided code",()=>{var o=FloatOptionItem.Registered.Values.ToArray();Check(o.Select(x=>x.Id).SequenceEqual(new[]{40110,40111,40112,40113,40114})&&o.Select(x=>x.Value).SequenceEqual(new[]{3f,3f,20f,10f,.75f}));Check(o[0].Rule.Equals(new FloatValueRule(1,10,.5f))&&o[1].Rule.Equals(new IntegerValueRule(1,10,1))&&o[2].Rule.Equals(new FloatValueRule(10,40,5))&&o[3].Rule.Equals(new FloatValueRule(5,20,2.5f))&&o[4].Rule.Equals(new FloatValueRule(.25f,3,.25f)));Check(o[0].Format==OptionFormat.Seconds&&o[1].Format==OptionFormat.Pieces&&o[2].Format==OptionFormat.Seconds&&o[3].Format==OptionFormat.Seconds);});
 Test("pet registration hooks and death cleanup observer installed only once",()=>{var r=Role();r.Add();r.OnSpawn();Check(PetActionManager.Handlers.Count==1&&CustomRoleManager.OnFixedUpdateOthers.Count==1&&CustomRoleManager.OnMurderPlayerOthers.Count==1);});
 Test("destroy unregisters own pet and global handlers",()=>{var r=Role();r.Dispose();Check(PetActionManager.Handlers.Count==0&&CustomRoleManager.OnFixedUpdateOthers.Count==0&&CustomRoleManager.OnMurderPlayerOthers.Count==0);});
 Test("old instance does not unregister a replacement pet handler",()=>{var r=Role();Action replacement=()=>{};PetActionManager.Handlers[1]=replacement;r.OnDestroy();Check(PetActionManager.Handlers[1]==replacement);});
 Test("initial cooldown stays 20 seconds even when tasks are ready",()=>{var r=Role();r.MyTaskState.CompletedTasksCount=3;Pet(r);Check(!Text(r).Contains("ファンサ中"));Tick(39);Pet(r);Check(!Text(r).Contains("ファンサ中"));Tick();Pet(r);Check(Text(r).Contains("ファンサ中"));});
 Test("insufficient completed tasks never activates",()=>{var r=Role();Tick(40);for(int n=0;n<3;n++){r.MyTaskState.CompletedTasksCount=n;Pet(r);Check(!Text(r).Contains("ファンサ中"));}});
 Test("one task set activates exactly once and consumes all tasks already completed",()=>{var r=Role();Ready(r);r.MyTaskState.CompletedTasksCount=5;Pet(r);Tick(6);Tick(40);Pet(r);Check(!Text(r).Contains("ファンサ中"));r.MyTaskState.CompletedTasksCount=7;Pet(r);Check(!Text(r).Contains("ファンサ中"));r.MyTaskState.CompletedTasksCount=8;Pet(r);Check(Text(r).Contains("ファンサ中"));});
 Test("pet spam never restarts fan or consumes an extra task set",()=>{var r=Role();var t=PC(2,new(1,0));Start(r);Tick(2);var before=Text(r);for(int n=0;n<10;n++)Pet(r);Check(Text(r)==before);Tick(4);Equal(Speed(t),1.75f);});
 Test("owner and in-sight target freeze then only target boosts",()=>{var r=Role();var t=PC(2,new(1,0));Start(r);Equal(Speed(r.Player),TownOfHost.Main.MinSpeed);Equal(Speed(t),TownOfHost.Main.MinSpeed);Tick(6);Equal(Speed(r.Player),1);Equal(Speed(t),1.75f);Tick(20);Equal(Speed(t),1);});
 Test("wall obstructed out of radius and dead players are not selected",()=>{var r=Role();var wall=PC(2,new(1,0));var far=PC(3,new(6,0));var dead=PC(4,new(2,0));dead.Data.IsDead=true;PhysicsHelpers.Blocked.Add(wall.Position);Start(r);Equal(Speed(wall),1);Equal(Speed(far),1);Equal(Speed(dead),1);Check(PhysicsHelpers.Calls>0);});
 Test("current light radius limits selection and radius boundary is included",()=>{var r=Role();ShipStatus.Instance.Radius=1;var edge=PC(2,new(1,0));var outp=PC(3,new(1.1f,0));Start(r);Equal(Speed(edge),TownOfHost.Main.MinSpeed);Equal(Speed(outp),1);});
 Test("target entering view after activation is not added",()=>{var r=Role();var t=PC(2,new(9,0));Start(r);t.Position=new(1,0);Equal(Speed(t),1);});
 Test("ladder vent moving platform and transition targets are skipped",()=>{var r=Role();var ts=Enumerable.Range(2,6).Select(i=>PC((byte)i,new(1,0))).ToArray();ts[0].onLadder=true;ts[1].inVent=true;ts[2].inMovingPlat=true;ts[3].walkingToVent=true;ts[4].MyPhysics.Animations.Ladder=true;ts[5].MyPhysics.Animations.EnterVent=true;Start(r);foreach(var t in ts)Equal(Speed(t),1);});
 Test("restricted caster cannot activate",()=>{foreach(int state in Enumerable.Range(0,6)){Reset();var r=Role();Ready(r);var p=r.Player;if(state==0)p.onLadder=true;if(state==1)p.inVent=true;if(state==2)p.inMovingPlat=true;if(state==3)p.walkingToVent=true;if(state==4)p.MyPhysics.Animations.Ladder=true;if(state==5)p.MyPhysics.Animations.EnterVent=true;Pet(r);Check(!Text(r).Contains("ファンサ中"));}});
 Test("target moving onto a ladder during fan is released without a boost",()=>{var r=Role();var t=PC(2,new(1,0));Start(r);t.onLadder=true;Tick();Equal(Speed(t),1);t.onLadder=false;Tick(5);Equal(Speed(t),1);});
 Test("caster restricted transition cancels fan safely",()=>{var r=Role();var t=PC(2,new(1,0));Start(r);r.Player.inMovingPlat=true;Tick();Equal(Speed(t),1);r.Player.inMovingPlat=false;Equal(Speed(r.Player),1);});
 Test("foreign CanMove false is never changed by start or end",()=>{var r=Role();var t=PC(2,new(1,0));var state=t.GetPlayerState();state.CanMove=false;Start(r);Check(!state.CanMove);Tick(6);Check(!state.CanMove);Equal(Speed(t),TownOfHost.Main.MinSpeed);Tick(20);Check(!state.CanMove);});
 Test("root applied by another role while frozen is preserved on release",()=>{var r=Role();var t=PC(2,new(1,0));Start(r);t.GetPlayerState().CanMove=false;Tick(6);Check(!t.GetPlayerState().CanMove);Equal(Speed(t),TownOfHost.Main.MinSpeed);t.GetPlayerState().CanMove=true;Equal(Speed(t),1.75f);});
 Test("external speed-based root overrides Idol boost",()=>{var r=Role();var t=PC(2,new(1,0));Start(r);Tick(6);TownOfHost.Main.AllPlayerSpeed[2]=TownOfHost.Main.MinSpeed;Equal(Speed(t),TownOfHost.Main.MinSpeed);Tick(20);Equal(TownOfHost.Main.AllPlayerSpeed[2],TownOfHost.Main.MinSpeed);});
 Test("base speed is not mutated during freeze boost or expiration",()=>{var r=Role();var t=PC(2,new(1,0));TownOfHost.Main.AllPlayerSpeed[2]=2;Start(r);Equal(TownOfHost.Main.AllPlayerSpeed[2],2);Tick(6);Equal(Speed(t),2.75f);Equal(TownOfHost.Main.AllPlayerSpeed[2],2);Tick(20);Equal(Speed(t),2);});
 Test("external additive multiplicative and absolute base changes survive boost expiration",()=>{var r=Role();var t=PC(2,new(1,0));Start(r);Tick(6);TownOfHost.Main.AllPlayerSpeed[2]+=1;Equal(Speed(t),2.75f);TownOfHost.Main.AllPlayerSpeed[2]*=2;Equal(Speed(t),4.75f);TownOfHost.Main.AllPlayerSpeed[2]=1.5f;Equal(Speed(t),2.25f);Tick(20);Equal(Speed(t),1.5f);});
 Test("speeding and Tiger multiplier remain composed with a bounded Idol boost",()=>{var r=Role();var t=PC(2,new(1,0));t.Speeding=true;new TownOfHost.Roles.Neutral.Tiger(t);Start(r);Tick(6);Equal(Speed(t),3.75f);Tick(20);Equal(Speed(t),3);});
 Test("overlapping Idols do not add their boosts together",()=>{var a=Role();var b=Role(3);b.Player.Position=new(0,1);var t=PC(2,new(1,0));b.MyTaskState.CompletedTasksCount=3;Ready(a);Pet(a);Pet(b);Tick(6);Equal(Speed(t),1.75f);Equal(TownOfHost.Main.AllPlayerSpeed[2],1);});
 Test("ending one Idol does not release the other Idols freeze",()=>{var a=Role();var b=Role(3);var t=PC(2,new(1,0));b.MyTaskState.CompletedTasksCount=3;Ready(a);Pet(a);Pet(b);a.OnDestroy();Equal(Speed(t),TownOfHost.Main.MinSpeed);b.OnDestroy();Equal(Speed(t),1);});
 Test("ending one boost preserves another source until its own expiry",()=>{var a=Role();var b=Role(3);var t=PC(2,new(1,0));b.MyTaskState.CompletedTasksCount=3;Ready(a);Pet(a);Pet(b);Tick(6);a.OnDestroy();Equal(Speed(t),1.75f);b.OnDestroy();Equal(Speed(t),1);});
 Test("boost uses amount at grant time even if settings later change",()=>{var r=Role();var t=PC(2,new(1,0));Start(r);Tick(6);FloatOptionItem.Registered["IdolSpeedUp"].Value=3;Equal(Speed(t),1.75f);Tick(20);Equal(Speed(t),1);});
 Test("final movement speed is clamped at the existing maximum",()=>{var r=Role();var t=PC(2,new(1,0));TownOfHost.Main.AllPlayerSpeed[2]=9.75f;Start(r);Tick(6);Equal(Speed(t),10);Tick(20);Equal(Speed(t),9.75f);});
 Test("owner death releases fan immediately without any boost",()=>{var r=Role();var t=PC(2,new(1,0));Start(r);r.Player.Data.IsDead=true;foreach(var action in CustomRoleManager.OnMurderPlayerOthers.ToArray())action(new());Equal(Speed(t),1);Tick(6);Equal(Speed(t),1);});
 Test("dead owner cleanup still runs from the hosts local tick",()=>{var r=Role();var t=PC(2,new(1,0));Start(r);r.Player.Data.IsDead=true;Tick();Equal(GameOptionsSender.LastSent[2],1);});
 Test("meeting clears freeze and boost without changing unrelated movement flags",()=>{foreach(bool boost in new[]{false,true}){Reset();var r=Role();var t=PC(2,new(1,0));Start(r);if(boost)Tick(6);t.GetPlayerState().CanMove=false;GameStates.IsMeeting=true;r.OnStartMeeting();GameStates.IsMeeting=false;Equal(Speed(t),TownOfHost.Main.MinSpeed);t.GetPlayerState().CanMove=true;Equal(Speed(t),1);}});
 Test("called meeting immediately disables composition before the meeting callback",()=>{var r=Role();var t=PC(2,new(1,0));Start(r);GameStates.CalledMeeting=true;Equal(Speed(t),1);Tick();GameStates.CalledMeeting=false;Equal(Speed(t),1);});
 Test("owner disconnect restores target and a reused target ID receives no old effect",()=>{var r=Role();var t=PC(2,new(1,0));Start(r);r.Player.Data.Disconnected=true;Tick();Equal(Speed(t),1);});
 Test("target PlayerId reuse never applies or removes effects on the replacement",()=>{var r=Role();var old=PC(2,new(1,0));Start(r);old.Data.Disconnected=true;var fresh=PC(2,new(1,0));TownOfHost.Main.AllPlayerSpeed[2]=2;Tick();Equal(Speed(fresh),2);Tick(6);Equal(Speed(fresh),2);});
 Test("target death removes boost without altering its base",()=>{var r=Role();var t=PC(2,new(1,0));Start(r);Tick(6);t.Data.IsDead=true;Tick();t.Data.IsDead=false;Equal(Speed(t),1);});
 Test("game end and reset leave no effects or pet handlers",()=>{var r=Role();var t=PC(2,new(1,0));Start(r);GameStates.InGame=false;Tick();Equal(Speed(t),1);Idol.Reset();Check(PetActionManager.Handlers.Count==0);GameStates.InGame=true;Equal(Speed(t),1);});
 Test("role disposal removes only its own modifier",()=>{var r=Role();var t=PC(2,new(1,0));Start(r);t.GetPlayerState().CanMove=false;r.Dispose();Check(!t.GetPlayerState().CanMove);t.GetPlayerState().CanMove=true;Equal(Speed(t),1);});
 Test("old owner replaced in the role map cannot activate",()=>{var r=Role();Ready(r);CustomRoleManager.AllActiveRoles.Remove(1);Pet(r);Check(!Text(r).Contains("ファンサ中"));});
 Test("non host cannot register a pet or commit state or speed effects",()=>{AmongUsClient.Instance.AmHost=false;var r=Role();Check(PetActionManager.Handlers.Count==0&&CustomRoleManager.Sent.Count==0);Equal(Idol.ApplyMovement(r.Player,2),2);});
 Test("dead meeting intro lobby and amnesia prevent activation",()=>{foreach(int state in Enumerable.Range(0,6)){Reset();var r=Role();Ready(r);if(state==0)r.Player.Data.IsDead=true;if(state==1)GameStates.IsMeeting=true;if(state==2)GameStates.Intro=true;if(state==3)GameStates.InGame=false;if(state==4)GameStates.IsInTask=false;if(state==5)TownOfHost.Roles.AddOns.Common.Amnesia.Blocked.Add(1);Pet(r);Check(!Text(r).Contains("ファンサ中"));}});
 Test("non local tick does not advance timers twice for large lobbies",()=>{var r=Role();r.MyTaskState.CompletedTasksCount=3;var t=PC(2);for(int n=0;n<100;n++)foreach(var action in CustomRoleManager.OnFixedUpdateOthers)action(t);Pet(r);Check(!Text(r).Contains("ファンサ中"));});
 Test("self lower text uses translated balanced TMP and is private",()=>{var r=Role();var other=PC(2);Check(Text(r).Contains("あとタスク3個"));var name=r.GetLowerText(r.Player);Check(name.EndsWith("</color></size>")&&name.Contains("#F8ABA6"));Check(r.GetLowerText(other)==""&&r.GetLowerText(r.Player,other)==""&&r.GetLowerText(r.Player,isForMeeting:true)=="");});
 Test("RPC carries bounded status only and uses reliable transport",()=>{var r=Role();var msg=CustomRoleManager.Sent.Last();Check(msg.Option==Hazel.SendOption.Reliable&&msg.Values.Length==4&&!(bool)msg.Values[0]&&(float)msg.Values[2]==20&&(int)msg.Values[3]==3);});
 Test("client receives status and interpolates display without changing authoritative effects",()=>{var r=Role();AmongUsClient.Instance.AmHost=false;r.ReceiveRPC(new(true,3f,0f,0));Check(Text(r).Contains("ファンサ中"));Tick();Check(Text(r).Contains("2.5"));Equal(Idol.ApplyMovement(r.Player,1),1);});
 Test("host refuses received status",()=>{var r=Role();r.ReceiveRPC(new(true,3f,0f,0));Check(!Text(r).Contains("ファンサ中"));});
 Test("malformed RPC leaves previous status unchanged",()=>{var r=Role();AmongUsClient.Instance.AmHost=false;foreach(var values in new[]{new object[]{true,float.NaN,0f,0},new object[]{true,11f,0f,0},new object[]{true,1f,float.PositiveInfinity,0},new object[]{true,1f,41f,0},new object[]{true,1f,0f,11}}){r.ReceiveRPC(new(values));Check(!Text(r).Contains("ファンサ中"));}});
 Test("settings flush represents the same freeze and boost for all recipients",()=>{var r=Role();var t=PC(2,new(1,0));Start(r);Equal(GameOptionsSender.LastSent[1],TownOfHost.Main.MinSpeed);Equal(GameOptionsSender.LastSent[2],TownOfHost.Main.MinSpeed);Tick(6);Equal(GameOptionsSender.LastSent[1],1);Equal(GameOptionsSender.LastSent[2],1.75f);Tick(20);Equal(GameOptionsSender.LastSent[2],1);});
 Test("same Idol regrant refreshes duration without adding speed twice",()=>{FloatOptionItem.Registered["IdolCooldown"].Value=10;FloatOptionItem.Registered["IdolBoostDuration"].Value=20;var r=Role();var t=PC(2,new(1,0));Start(r);Tick(6);Equal(Speed(t),1.75f);r.MyTaskState.CompletedTasksCount=6;Tick(20);Pet(r);Tick(6);Equal(Speed(t),1.75f);Equal(TownOfHost.Main.AllPlayerSpeed[2],1);Tick(40);Equal(Speed(t),1);});
 Test("stronger overlapping boost wins and its removal preserves a weaker boost",()=>{var a=Role();var b=Role(3);var t=PC(2,new(1,0));b.MyTaskState.CompletedTasksCount=3;Ready(a);Pet(a);Tick(6);FloatOptionItem.Registered["IdolSpeedUp"].Value=3;Pet(b);Tick(6);Equal(Speed(t),4);b.OnDestroy();Equal(Speed(t),1.75f);Tick(14);Equal(Speed(t),1);});
 Test("another role unlocking movement cannot release an active Idol freeze",()=>{var r=Role();var t=PC(2,new(1,0));Start(r);t.GetPlayerState().CanMove=false;t.GetPlayerState().CanMove=true;Equal(Speed(t),TownOfHost.Main.MinSpeed);Tick(6);Equal(Speed(t),1.75f);});
 Test("distinct CLR wrappers for the same native target retain freeze and boost",()=>{var r=Role();var t=PC(2,new(1,0));var alias=new PlayerControl{PlayerId=t.PlayerId,NativeIdentity=t.NativeIdentity,Data=t.Data,MyPhysics=t.MyPhysics,Position=t.Position};Check(t==alias&&!t.Equals(alias),"fixture must model IL2CPP wrapper identity");Start(r);Equal(Speed(alias),TownOfHost.Main.MinSpeed,"same-native target freeze");Tick(6);Equal(Speed(alias),1.75f,"same-native target boost");Tick(20);Equal(Speed(alias),1);});
 Test("three of four tasks unlocks through actual pet dispatch without fourth task",()=>{var r=Role();var target=PC(2,new(1,0));r.MyTaskState.AllTasksCount=4;r.MyTaskState.CompletedTasksCount=2;Tick(40);Pet(r);Check(!Text(r).Contains("ファンサ中")&&Logger.Entries.Any(e=>e.Tag=="Idol"&&e.Message.Contains("reason=TASKS")));r.MyTaskState.CompletedTasksCount=3;r.OnCompleteTask(1);Pet(r);Check(Text(r).Contains("ファンサ中"));Equal(GameOptionsSender.LastSent[2],TownOfHost.Main.MinSpeed);Check(Logger.Entries.Any(e=>e.Message.Contains("completed=3 total=4")&&e.Message.Contains("reason=READY")));});
 Test("four of four tasks also unlocks and still needs new tasks for reuse",()=>{var r=Role();r.MyTaskState.CompletedTasksCount=4;Tick(40);Pet(r);Check(Text(r).Contains("ファンサ中"));Tick(46);Pet(r);Check(!Text(r).Contains("ファンサ中"));});
 Test("settings sender with another native wrapper receives freeze boost and restore",()=>{var r=Role();var t=PC(2,new(1,0));var sender=GameOptionsSender.AllSenders.OfType<PlayerGameOptionsSender>().Single(x=>x.player==t);sender.player=new(){PlayerId=2,NativeIdentity=t.NativeIdentity,Data=t.Data,MyPhysics=t.MyPhysics,Position=t.Position};Start(r);Equal(GameOptionsSender.LastSent[2],TownOfHost.Main.MinSpeed);Tick(6);Equal(GameOptionsSender.LastSent[2],1.75f);Tick(20);Equal(GameOptionsSender.LastSent[2],1);});
 Test("same PlayerId with different native identity is never mistaken for affected target",()=>{var r=Role();var t=PC(2,new(1,0));Start(r);var other=PC(2,new(1,0));Equal(Speed(other),1);Tick(6);Equal(Speed(other),1);});
 Test("actual common pet dispatcher still calls another roles registered handler",()=>{var pc=PC(2);int count=0;PetActionManager.Handlers[2]=()=>count++;RealPetDispatch.OnPetUse(pc);Check(count==1);pc.inVent=true;RealPetDispatch.OnPetUse(pc);Check(count==1);pc.inVent=false;AmongUsClient.Instance.AmHost=false;RealPetDispatch.OnPetUse(pc);Check(count==1);});
 Test("pet diagnostics identify cooldown and ongoing fan rejection",()=>{var r=Role();r.MyTaskState.CompletedTasksCount=3;Pet(r);Check(Logger.Entries.Any(e=>e.Tag=="Idol"&&e.Message.Contains("cooldown=20.00")&&e.Message.Contains("reason=COOLDOWN")));Tick(40);Pet(r);Pet(r);Check(Logger.Entries.Any(e=>e.Tag=="Idol"&&e.Message.Contains("reason=FAN_ACTIVE")));});
 Test("no targets still activates self freeze without a hidden player count requirement",()=>{var r=Role();Start(r);Equal(Speed(r.Player),TownOfHost.Main.MinSpeed);Check(Logger.Entries.Any(e=>e.Tag=="Idol"&&e.Message.Contains("FAN_START")&&e.Message.Contains("targets=0")));});
 Test("selection diagnostics distinguish wall range and restricted movement",()=>{var r=Role();var a=PC(2,new(1,0));PhysicsHelpers.Blocked.Add(a.Position);PC(3,new(9,0));PC(4).inVent=true;Start(r);foreach(var reason in new[]{"WALL_BLOCKED","OUT_OF_SIGHT","RESTRICTED_MOVEMENT"})Check(Logger.Entries.Any(e=>e.Tag=="Idol"&&e.Message.Contains("result="+reason)));});
 Test("effect logs record prepared speeds and expiration without asserting delivery",()=>{var r=Role();PC(2,new(1,0));Start(r);Tick(6);Tick(20);var messages=Logger.Entries.Where(e=>e.Tag=="Idol").Select(e=>e.Message).ToArray();foreach(var term in new[]{"FAN_START","FAN_END","BOOST_END","preparedSpeed=0.0001","preparedSpeed=1.7500","preparedSpeed=1.0000","delivery=UNCONFIRMED"})Check(messages.Any(s=>s.Contains(term)),term);});
 Test("diagnostics never contain names or account identifiers and do not log per tick",()=>{var r=Role();PC(2,new(1,0));Start(r);int before=Logger.Entries.Count(e=>e.Tag=="Idol");Tick(5);Check(Logger.Entries.Count(e=>e.Tag=="Idol")==before);Check(Logger.Entries.Where(e=>e.Tag=="Idol").All(e=>!e.Message.Contains("FAKE_NAME_PRIVATE")&&!e.Message.Contains("FriendCode")&&!e.Message.Contains("PUID")));});
 Test("meeting cleanup logs restoration without changing foreign movement lock",()=>{var r=Role();var t=PC(2,new(1,0));Start(r);t.GetPlayerState().CanMove=false;r.OnStartMeeting();Check(Logger.Entries.Any(e=>e.Tag=="Idol"&&e.Message.Contains("EFFECT_CLEAR reason=MEETING")));Check(!t.GetPlayerState().CanMove);});
 Test("stale-role and foreign movement lock rejection have explicit reasons",()=>{var r=Role();Ready(r);r.Player.GetPlayerState().CanMove=false;Pet(r);Check(Logger.Entries.Any(e=>e.Tag=="Idol"&&e.Message.Contains("reason=MOVEMENT_LOCKED")));CustomRoleManager.AllActiveRoles.Remove(1);Pet(r);Check(Logger.Entries.Any(e=>e.Tag=="Idol"&&e.Message.Contains("reason=STALE_ROLE_OR_PLAYER")));});
 Console.WriteLine($"RESULT {passed} passed, 0 failed (actual Idol + extracted game-options speed pipeline; real extracted pet dispatcher; Unity, task and transport substitutes)");
 }
}

